import yfinance as yf; tickers=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]; data=yf.download(tickers,period="3mo",progress=False,auto_adjust=True); close=data["Close"]; volume=data["Volume"]; delta=close.diff(); gain=delta.clip(lower=0).rolling(14).mean(); loss=(-delta.clip(upper=0)).rolling(14).mean(); rsi=100-(100/(1+gain/loss)); print("\n".join((lambda p,p5,mm20,rvol,r,s:f"{t}: {p:.2f} | Var 5j: {p5:+.2f}% | MM20: {mm20:.2f} | RVOL: {rvol:.2f} | RSI14: {r:.1f} | Score: {s}/100 | Signal: {'SURCHAUFFE' if p5>=8 or r>=75 else 'ACHAT' if s>=70 and 50<=r<70 else 'SURVEILLANCE' if s>=40 or 45<=r<75 else 'AUCUN SIGNAL'}")(float(close[t].dropna().iloc[-2]),(float(close[t].dropna().iloc[-2])/float(close[t].dropna().iloc[-7])-1)*100,float(close[t].dropna().iloc[-21:-1].mean()),float(volume[t].dropna().iloc[-2])/float(volume[t].dropna().iloc[-21:-1].mean()),float(rsi[t].iloc[-2]),(40 if float(close[t].dropna().iloc[-2])>float(close[t].dropna().iloc[-21:-1].mean()) else 0)+(30 if 3<(float(close[t].dropna().iloc[-2])/float(close[t].dropna().iloc[-7])-1)*100<8 else 0)+(30 if float(volume[t].dropna().iloc[-2])/float(volume[t].dropna().iloc[-21:-1].mean())>=1.5 else 0)) for t in tickers if t in close.columns and close[t].dropna().shape[0]>=21))
